birdConfiguration:
router id 10.240.1.4;
protocol device { scan time 5; }
protocol kernel {
 persist;
 merge paths on;
 ipv4 { import none; export filter { if source = RTS_BGP then accept; reject; }; };
}
protocol static gateway_reachability { ipv4; route 10.250.0.12/32 via "xfrm100"; route 10.250.0.13/32 via "xfrm101"; }
protocol static lab_advertisements { ipv4; route 10.60.0.0/16 blackhole;
route 10.61.1.0/24 blackhole;
route 10.230.0.0/16 blackhole; }

protocol bgp azure0 {
 local 10.240.1.4 as 65011;
 neighbor 10.250.0.12 as 65515;
 multihop 2;
 hold time 30;
 keepalive time 10;
 ipv4 {
  import all;
  export filter { if proto = "lab_advertisements" then { bgp_path.prepend(65011); bgp_path.prepend(65011); bgp_path.prepend(65011); accept; } reject; };
  next hop self;
 };
}

